DELETE FROM public.precios_recursos_mercado AS p
USING cotizat_precios_latam_stage AS s
WHERE p.organizacion_id IS NULL AND p.pais_codigo = s.pais_codigo
  AND (p.codigo_recurso = s.codigo_recurso OR p.recurso_id IN (SELECT r.id FROM public.recursos AS r WHERE r.codigo = s.codigo_recurso));
INSERT INTO public.precios_recursos_mercado (
  recurso_id, codigo_recurso, pais_codigo, organizacion_id,
  precio, moneda, precio_min, precio_max, unidad_referencia,
  fuente, proveedor, confianza, fecha_consulta, fecha_vigencia,
  incluye_iva, incluye_transporte, observaciones, fecha_actualizacion, activo
)
SELECT recurso.id, s.codigo_recurso, s.pais_codigo, NULL, s.precio, s.moneda, s.precio_min, s.precio_max, s.unidad_referencia, s.fuente, '', s.confianza, s.fecha_consulta, NULL, s.incluye_iva, s.incluye_transporte, s.observaciones, CURRENT_TIMESTAMP, true
FROM cotizat_precios_latam_stage AS s
CROSS JOIN LATERAL (SELECT r.id FROM public.recursos AS r WHERE r.codigo = s.codigo_recurso ORDER BY r.id LIMIT 1) AS recurso;
COMMIT;
SELECT pais_codigo, count(*) FROM public.precios_recursos_mercado WHERE organizacion_id IS NULL AND activo IS TRUE AND pais_codigo='EC' GROUP BY pais_codigo;
